// Synthetic respondents for testing the 50-question test and the MBTI layer.
//
// Each simulated person has a known "true" Big Five profile θ (latent, correlated as in the real data) and a known
// true MBTI type. Their answers are generated by an ordinal factor model fitted to 59,492 real people
// (scripts/sim/fit_item_model.ts), so simulated answer patterns, reliabilities and trait correlations match real ones.
//
// The true MBTI type uses the app's own assumptions: each MBTI scale = NEO correlations · θ + an unexplained part,
// scaled to unit variance and cut at the UK population split. So "recovery" here is an upper bound on real-world
// accuracy: it measures the app against its own model, not against the official MBTI.
import itemModel from "./ipipItemModel.json";
import { IPIP_ITEMS, DEFAULT_ANSWERS, type Answers } from "@/lib/questions";
import { currentZ, measurement, phi, type Vec } from "@/lib/model";
import { DIMS, MBTI_DIM_MODEL, MBTI_PREVALENCE_UK, mbtiLetters, modelFor } from "@/lib/mbti";
import { TRAITS, type Trait } from "@/lib/params";

export type Dim = (typeof DIMS)[number];
export const NEO_W: Record<Dim, Partial<Record<Trait, number>>> = {
  EI: { E: -0.72, N: 0.16 },
  SN: { O: 0.71, E: 0.15 },
  TF: { A: 0.45, C: -0.18, N: 0.15 },
  JP: { C: -0.48, O: 0.28, E: 0.17 },
};
const ORDER: Trait[] = ["O", "C", "E", "A", "N"]; // order of itemModel.R

export function rng(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export type Rand = () => number;
export const gauss = (r: Rand) => Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());

function cholesky(A: number[][]) {
  const n = A.length;
  const L = A.map(() => Array(n).fill(0));
  for (let i = 0; i < n; i++)
    for (let j = 0; j <= i; j++) {
      let s = A[i][j];
      for (let k = 0; k < j; k++) s -= L[i][k] * L[j][k];
      L[i][j] = i === j ? Math.sqrt(s) : s / L[j][j];
    }
  return L;
}
const CHOL = cholesky(itemModel.R);
export const TRAIT_R: Record<Trait, Record<Trait, number>> = Object.fromEntries(
  ORDER.map((a, i) => [a, Object.fromEntries(ORDER.map((b, j) => [b, itemModel.R[i][j]]))]),
) as never;

/** A random true personality, correlated like real adults. */
export function drawTheta(r: Rand): Vec {
  const e = ORDER.map(() => gauss(r));
  const x = CHOL.map((row) => row.reduce((s, l, k) => s + l * e[k], 0));
  return Object.fromEntries(ORDER.map((t, i) => [t, x[i]])) as Vec;
}

/** Variance of c·θ given the trait correlations (the app's model assumes the traits are uncorrelated). */
export const quadForm = (w: Partial<Record<Trait, number>>) =>
  (Object.entries(w) as [Trait, number][]).reduce((s, [a, wa]) => s + (Object.entries(w) as [Trait, number][]).reduce((u, [b, wb]) => u + wa * wb * TRAIT_R[a][b], 0), 0);

/** The person's true continuous MBTI scales (unit variance), given θ and their unexplained parts. */
export function trueScales(theta: Vec, resid: number[]): number[] {
  return DIMS.map((d, i) => {
    const w = NEO_W[d];
    const s = (Object.entries(w) as [Trait, number][]).reduce((a, [t, c]) => a + c * theta[t], 0);
    return s + Math.sqrt(1 - quadForm(w)) * resid[i];
  });
}
export const typeFromScales = (s: number[]) => DIMS.map((d, i) => (s[i] > MBTI_DIM_MODEL[d].cut ? MBTI_DIM_MODEL[d].second : MBTI_DIM_MODEL[d].first)).join("");

export type Person = { theta: Vec; resid: number[]; type: string };
export function drawPerson(r: Rand): Person {
  const theta = drawTheta(r);
  const resid = DIMS.map(() => gauss(r));
  return { theta, resid, type: typeFromScales(trueScales(theta, resid)) };
}

/** One sitting of the 50-question test (answers 1–5 in IPIP_ITEMS order) for a person with true profile θ. */
export function answer(theta: Vec, r: Rand, opts: { stateSd?: number } = {}): number[] {
  // Optional day-to-day state wobble on each trait (real retests over weeks are a little less stable than alpha).
  const state = Object.fromEntries(TRAITS.map((t) => [t, (opts.stateSd ?? 0) * gauss(r)])) as Vec;
  const idx: Record<Trait, number> = { O: 0, C: 0, E: 0, A: 0, N: 0 };
  return IPIP_ITEMS.map((it) => {
    const p = (itemModel.items as Record<Trait, { tau: number[]; lambda: number }[]>)[it.trait][idx[it.trait]++];
    const y = p.lambda * (theta[it.trait] + state[it.trait]) + Math.sqrt(1 - p.lambda * p.lambda) * gauss(r);
    const keyed = 1 + p.tau.filter((c) => y > c).length;
    return it.reverse ? 6 - keyed : keyed;
  });
}

export const detailedAnswers = (ipip: number[]): Answers => ({ ...DEFAULT_ANSWERS, inventory: "detailed", ipip });

/** Exactly what the results page shows: z-scores and reliabilities from the answers, then the closest type. */
export function appType(ipip: number[], scorer: Scorer = "app") {
  const a = detailedAnswers(ipip);
  const z = currentZ(a);
  const rel = measurement(a).rel;
  return { z, rel, ...classify(z, rel, scorer) };
}

export type Scorer = "app" | "likeliest";
/**
 * "app": the shipped rule (type cut = population cut × √r², so each type is given out about as often as in the UK).
 * "likeliest": the previous rule, the letter with P > 50% against the raw population cut. Kept for comparison.
 */
export function classify(z: Vec, rel: Vec, scorer: Scorer) {
  const L = mbtiLetters(z, rel);
  if (scorer === "app") return { type: L.map((l) => l.letter).join(""), letters: L };
  const M = modelFor(rel);
  const type = DIMS.map((d) => {
    const m = M[d];
    const s = (Object.entries(m.w) as [Trait, number][]).reduce((a, [t, w]) => a + w * z[t], 0);
    return s > m.cut ? m.second : m.first;
  }).join("");
  return { type, letters: L };
}

export const lettersSame = (a: string, b: string) => [...a].filter((c, i) => c === b[i]).length;

export const PREVALENCE = MBTI_PREVALENCE_UK;
export { phi };
